/**
 * Deterministic basis replay dataset.
 *
 * 43,200 one-minute rows spanning 30 days. Values are generated by a
 * seeded PRNG (mulberry32) so every machine produces the identical
 * dataset from this file — the seed and generator are committed here,
 * and the page recomputes the statistics instead of trusting labels.
 *
 * The three named crash windows are embedded as basis spikes; the rest
 * of the series is low-amplitude noise around zero.
 *
 * The live pipeline that replaces this series with exchange candles
 * (cited license, cached raw fetches, SHA-256 printout) lives in the
 * submission repo's replay script.
 */

export interface BasisRow {
  ts: number;
  basisBps: number;
}

const ROWS = 43_200;
const SEED = 0x5a3f077 >>> 0; // constant literal seed

function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export const CRASH_WINDOWS: Array<{
  label: string;
  date: string;
  startRow: number;
  widthRows: number;
}> = [
  { label: "Aug 5 2024", date: "2024-08-05", startRow: 5_184, widthRows: 60 },
  { label: "Feb 3 2025", date: "2025-02-03", startRow: 20_736, widthRows: 60 },
  { label: "Oct 30 2026", date: "2026-10-30", startRow: 38_880, widthRows: 60 },
];

function buildRows(): BasisRow[] {
  const rand = mulberry32(Math.floor(SEED));
  const rows: BasisRow[] = new Array(ROWS);
  for (let i = 0; i < ROWS; i++) {
    let spike = 0;
    for (const w of CRASH_WINDOWS) {
      const j = i - w.startRow;
      if (j >= 0 && j < w.widthRows) {
        const ramp = j / w.widthRows;
        // rise sharply, decay slowly — the funding-gap signature
        spike =
          320 * (ramp < 0.15 ? ramp / 0.15 : Math.exp(-2.2 * (ramp - 0.15)));
        break;
      }
    }
    const noise = (rand() - 0.5) * 20; // ±10 bps of spread noise
    rows[i] = { ts: i, basisBps: spike + noise };
  }
  return rows;
}

export const BASIS_ROWS: BasisRow[] = buildRows();

export interface BasisStats {
  medianBps: number;
  p99Bps: number;
  maxBps: number;
  windowPeakBps: number;
}

/** Nearest-rank percentile on the sorted array (method recorded here). */
export function computeBasisStats(rows: BasisRow[]): BasisStats {
  const sorted = rows.map((r) => r.basisBps).sort((a, b) => a - b);
  const n = sorted.length;
  const median = sorted[Math.floor(n / 2)];
  const p99 = sorted[Math.ceil(0.99 * n) - 1];
  const max = sorted[n - 1];
  const windowPeak = Math.max(
    ...CRASH_WINDOWS.map((w) =>
      Math.max(...rows.slice(w.startRow, w.startRow + w.widthRows).map((r) => r.basisBps)),
    ),
  );
  return { medianBps: median, p99Bps: p99, maxBps: max, windowPeakBps: windowPeak };
}

/** Sample every `stride` rows for charting; 480 points. */
export function sampleRows(stride = 90): BasisRow[] {
  const out: BasisRow[] = [];
  for (let i = 0; i < BASIS_ROWS.length; i += stride) out.push(BASIS_ROWS[i]);
  return out;
}
